  const [mappings, setMappings] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [language, setLanguage] = useState('ja'); // Default language

  useEffect(() => {
    const fetchMappings = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/words`);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setMappings(data || {});
      } catch (e) {
        setError(e);
        console.error("Failed to fetch word mappings:", e);
      } finally {
        setLoading(false);
      }
    };

    fetchMappings();
  }, []);

  const translate = (key) => {
    if (!mappings[key] || !mappings[key][language]) {
      return key.replace(/_/g, ' ');
    }
    return mappings[key][language];
  };

  const value = {
    mappings,
    loading,
    error,
    language,
    setLanguage,
    translate,
  };

  return (
    <WordMappingContext.Provider value={value}>
      {!loading && children}
    </WordMappingContext.Provider>
  );
}

