            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default SchoolDetailPage;

import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';

function StudentCountTable({ details }) {
  const { translate } = useWordMappings();

  const { table, grades, gradeNames } = useMemo(() => {
    const data = {};
    const grades = new Set();
    const gradeNameMapping = {}; // To store translated grade names

    // This regex is designed to be flexible, matching keys like
    // 'grade_1_boys', 'high_school_3_total', etc.
    const keyRegex = /^(.*)_(boys|girls|total)$/;

    for (const [key, value] of Object.entries(details)) {
      const match = key.match(keyRegex);
      if (!match) continue;

      const [, gradeKey, metric] = match;

      if (!data[gradeKey]) {
        data[gradeKey] = {};
        grades.add(gradeKey);
        gradeNameMapping[gradeKey] = translate(gradeKey);
      }
      data[gradeKey][metric] = value;
    }

    // A more robust sorting for grade keys
    const sortedGrades = Array.from(grades).sort((a, b) => {
      const numA = parseInt(a.match(/\d+$/)?.[0] || '0');
      const numB = parseInt(b.match(/\d+$/)?.[0] || '0');
      if (a.includes('high') && !b.includes('high')) return 1;
      if (!a.includes('high') && b.includes('high')) return -1;
      return numA - numB;
    });

    return { table: data, grades: sortedGrades, gradeNames: gradeNameMapping };
  }, [details, translate]);

  if (grades.length === 0) {
    return <p>{translate('no_student_count_data')}</p>;
  }

  return (
    <div className="table-responsive">
      <table className="table table-bordered table-striped text-center">
        <thead>
          <tr>
            <th>{/* Empty top-left corner */}</th>
            {grades.map(gradeKey => (
              <th key={gradeKey}>{gradeNames[gradeKey]}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>{translate('boys')}</td>
            {grades.map(gradeKey => (
              <td key={gradeKey}>{table[gradeKey]?.boys ?? '-'}</td>
            ))}
          </tr>
          <tr>
            <td>{translate('girls')}</td>
            {grades.map(gradeKey => (
              <td key={gradeKey}>{table[gradeKey]?.girls ?? '-'}</td>
            ))}
          </tr>
          <tr>
            <td className="fw-bold">{translate('total')}</td>
            {grades.map(gradeKey => (
              <td key={gradeKey} className="fw-bold">{table[gradeKey]?.total ?? '-'}</td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
}

export default StudentCountTable;

