import React, { useMemo } from 'react';

function StudentCountTable({ studentCountData }) {

  const { table, grades } = useMemo(() => {
    if (!studentCountData || typeof studentCountData !== 'object') {
      return { table: {}, grades: [] };
    }
    const gradeKeys = Object.keys(studentCountData);

    // Sort grades logically (e.g., 中1, 中2, ..., 高1, 高2, ...)
    gradeKeys.sort((a, b) => {
      const isAHs = a.startsWith('高');
      const isBHs = b.startsWith('高');
      const numA = parseInt(a.replace(/[^0-9]/g, ''));
      const numB = parseInt(b.replace(/[^0-9]/g, ''));

      if (isAHs && !isBHs) return 1;
      if (!isAHs && isBHs) return -1;
      return numA - numB;
    });

    return { table: studentCountData, grades: gradeKeys };
  }, [studentCountData]);

  if (grades.length === 0) {
    return <p>生徒数のデータがありません。</p>;
  }

  return (
    <div className="table-responsive">
      <table className="table table-bordered table-striped text-center">
        <thead>
          <tr>
            <th>{/* Empty top-left corner */}</th>
            {grades.map(grade => (
              <th key={grade}>{grade}</th>
