import React from 'react';
import { Pie } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';

ChartJS.register(ArcElement, Tooltip, Legend);

const GenderPieChart = ({ boys, girls, title }) => {
  const data = {
    labels: ['男子', '女子'],
    datasets: [
      {
        label: '生徒数',
        data: [boys, girls],
        backgroundColor: [
          'rgba(54, 162, 235, 0.6)',
          'rgba(255, 99, 132, 0.6)',
        ],
        borderColor: [
          'rgba(54, 162, 235, 1)',
          'rgba(255, 99, 132, 1)',
        ],
        borderWidth: 1,
      },
    ],
  };

  const options = {
    responsive: true,
    plugins: {
      legend: {
        display: true,
        position: 'top',
      },
      title: {
        display: true,
        text: title,
      },
    },
  };

  // Render chart only if there is data to show
  if (boys === 0 && girls === 0) {
    return null;
  }

  return <Pie data={data} options={options} />;
};

export default GenderPieChart;

import React, { useMemo } from 'react';
import GenderPieChart from './GenderPieChart';

function StudentCountTable({ studentCountData }) {

  const { table, grades, columnTotals } = useMemo(() => {
    if (!studentCountData || typeof studentCountData !== 'object') {
      return { table: {}, grades: [], columnTotals: {} };
    }

    const gradeKeys = Object.keys(studentCountData);
    const processedTable = {};
    const totals = { boys: 0, girls: 0, total: 0 };

    // Sort grades logically first
    gradeKeys.sort((a, b) => {
      const isAHs = a.startsWith('高');
      const isBHs = b.startsWith('高');
      const numA = parseInt(a.replace(/[^0-9]/g, ''), 10);
      const numB = parseInt(b.replace(/[^0-9]/g, ''), 10);

      if (isAHs && !isBHs) return 1;
      if (!isAHs && isBHs) return -1;
      return numA - numB;
    });

    // Process data and calculate totals
    gradeKeys.forEach(grade => {
      const metrics = studentCountData[grade];
      if (typeof metrics !== 'object' || metrics === null) return;

      const boys = parseInt(metrics['男子'], 10) || 0;
      const girls = parseInt(metrics['女子'], 10) || 0;
      const total = boys + girls; // Calculate total row

      processedTable[grade] = { boys, girls, total };

      totals.boys += boys;
      totals.girls += girls;
      totals.total += total;
    });

    return { table: processedTable, grades: gradeKeys, columnTotals: totals };
  }, [studentCountData]);

  const formatGrade = (grade) => {
    const num = grade.replace(/[^0-9]/g, '');
    // Handle cases where num might be empty
    return num ? `${num}年` : grade;
  };

  const formatCount = (count) => {
    if (count === null || typeof count === 'undefined') return '-';
    const num = parseInt(count, 10);
    return isNaN(num) ? '-' : `${num.toLocaleString()}名`;
  };

  if (grades.length === 0) {
    return <p>生徒数のデータがありません。</p>;
  }

  return (
    <div style={{ width: '80%', margin: '0 auto' }}>
      <div className="table-responsive">
        <table className="table table-bordered table-striped text-center">
          <thead>
            <tr>
              <th>{/* Empty */}</th>
              {grades.map(grade => (
                <th key={grade}>{formatGrade(grade)}</th>
              ))}
              <th className="table-dark">総合計</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>男子</td>
              {grades.map(grade => (
                <td key={grade}>{formatCount(table[grade]?.boys)}</td>
              ))}
              <td>{formatCount(columnTotals.boys)}</td>
            </tr>
            <tr>
              <td>女子</td>
              {grades.map(grade => (
                <td key={grade}>{formatCount(table[grade]?.girls)}</td>
              ))}
              <td>{formatCount(columnTotals.girls)}</td>
            </tr>
            <tr>
              <td className="fw-bold">合計</td>
              {grades.map(grade => (
                <td key={grade} className="fw-bold">{formatCount(table[grade]?.total)}</td>
              ))}
              <td className="fw-bold table-dark">{formatCount(columnTotals.total)}</td>
            </tr>
          </tbody>
        </table>
      </div>

      <div className="row mt-5">
        {grades.map(grade => (
          <div key={grade} className="col-md-6 mb-4">
            <GenderPieChart 
              boys={table[grade]?.boys || 0} 
              girls={table[grade]?.girls || 0} 
              title={`${formatGrade(grade)} 男女比`}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

export default StudentCountTable;

