import React, { useMemo } from 'react';
import GenderPieChart from './GenderPieChart';

function StudentCountTable({ studentCountData }) {

  const { tableData, columnTotals } = useMemo(() => {
    if (!Array.isArray(studentCountData)) {
      return { tableData: [], columnTotals: { boys: 0, girls: 0, total: 0 } };
    }

    // Sort the array based on the grade name
    studentCountData.sort((a, b) => {
      const gradeA = a.学年 || '';
      const gradeB = b.学年 || '';
      const isAHs = gradeA.startsWith('高');
      const isBHs = gradeB.startsWith('高');
      const numA = parseInt(gradeA.replace(/[^0-9]/g, ''), 10) || 0;
      const numB = parseInt(gradeB.replace(/[^0-9]/g, ''), 10) || 0;

      if (isAHs && !isBHs) return 1;
      if (!isAHs && isBHs) return -1;
      return numA - numB;
    });

    const totals = { boys: 0, girls: 0, total: 0 };

    const processedData = studentCountData.map(item => {
      const boys = parseInt(item['男子'], 10) || 0;
      const girls = parseInt(item['女子'], 10) || 0;
      const total = boys + girls; // Always calculate the total

      totals.boys += boys;
      totals.girls += girls;
      totals.total += total;

      return {
        grade: item['学年'],
        boys: boys,
        girls: girls,
        total: total,
      };
    });

    return { tableData: processedData, columnTotals: totals };
  }, [studentCountData]);

  const formatCount = (count) => {
    if (count === null || typeof count === 'undefined') return '-';
    const num = parseInt(count, 10);
    return isNaN(num) ? '-' : `${num.toLocaleString()}名`;
  };

  if (tableData.length === 0) {
    return <p>生徒数のデータがありません。</p>;
  }

  return (
    <div style={{ width: '95%', margin: '0 auto' }}>
