              ))}
              <th className="fw-bold">全体</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>男子</td>
              {tableData.map(item => (
                <td key={item.grade}>{formatCount(item.boys)}</td>
              ))}
              <td>{formatCount(columnTotals.boys)}</td>
            </tr>
            <tr>
              <td>女子</td>
              {tableData.map(item => (
                <td key={item.grade}>{formatCount(item.girls)}</td>
              ))}
              <td>{formatCount(columnTotals.girls)}</td>
            </tr>
            <tr>
              <td className="fw-bold">合計</td>
              {tableData.map(item => (
