import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';

// Helper to sort grade keys like 中1, 中2, ..., 高1, 高2, ...
const sortGradeKeys = (gradeKeys) => {
  return gradeKeys.sort((a, b) => {
    const isAHs = a.startsWith('高');
    const isBHs = b.startsWith('高');
    const numA = parseInt(a.replace(/[^0-9]/g, ''), 10) || 0;
    const numB = parseInt(b.replace(/[^0-9]/g, ''), 10) || 0;

    if (isAHs && !isBHs) return 1;
    if (!isAHs && isBHs) return -1;
    return numA - numB;
  });
};

function ClassCompositionDetails({ details }) {
  const { translate } = useWordMappings();

  const { classCountData, otherDetailsData } = useMemo(() => {
    // Find the keys for each piece of data
    const countKey = Object.keys(details).find(k => k.includes('クラス数'));
    const courseKey = Object.keys(details).find(k => k.includes('文理別コース'));
    const perClassKey = Object.keys(details).find(k => k.includes('1クラスあたりの人数'));
    const otherCourseKey = Object.keys(details).find(k => k.includes('その他コース'));

    // --- 1. Process Class Count Data ---
    let classCountData = {};
    if (countKey && details[countKey] && typeof details[countKey] === 'string') {
      try { classCountData = JSON.parse(details[countKey]); } catch (e) {}
    }

    // --- 2. Process Other Details Data ---
    const otherDetails = [];
    const tempOtherData = {};

    const processOtherKey = (key, name) => {
      if (key && details[key] && typeof details[key] === 'string') {
        try {
          const parsed = JSON.parse(details[key]);
          for (const [grade, value] of Object.entries(parsed)) {
            if (!tempOtherData[grade]) tempOtherData[grade] = {};
            tempOtherData[grade][name] = value;
          }
        } catch (e) {}
      }
    };

    processOtherKey(courseKey, translate(courseKey));
    processOtherKey(perClassKey, translate(perClassKey));
    processOtherKey(otherCourseKey, translate(otherCourseKey));

    const sortedOtherGrades = sortGradeKeys(Object.keys(tempOtherData));

    for (const grade of sortedOtherGrades) {
      for (const [desc, value] of Object.entries(tempOtherData[grade])) {
        if (value) { // Only add if there is a value
          otherDetails.push({ id: `${grade}-${desc}`, grade, desc, value });
        }
      }
    }

    return { classCountData, otherDetailsData: otherDetails };
  }, [details, translate]);

  const sortedClassCountGrades = useMemo(() => sortGradeKeys(Object.keys(classCountData)), [classCountData]);

  return (
    <div>
      {/* Table 1: Class Counts */}
      {sortedClassCountGrades.length > 0 && (
        <div className="mb-4">
          <h5 className="fw-bold">{translate('unmapped_ja_クラス数')}</h5>
          <div className="table-responsive">
            <table className="table table-bordered text-center">
              <thead>
                <tr>
                  {sortedClassCountGrades.map(grade => <th key={grade}>{grade}</th>)}
                </tr>
              </thead>
              <tbody>
                <tr>
                  {sortedClassCountGrades.map(grade => <td key={grade}>{classCountData[grade]}</td>)}
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Table 2: Other Details (borderless) */}
      {otherDetailsData.length > 0 && (
        <div className="mb-4">
          <h5 className="fw-bold">{translate('other_class_information')}</h5>
          <table className="table">
            <tbody>
              {otherDetailsData.map(item => (
                <tr key={item.id}>
                  <td style={{ width: '20%' }}><strong>{item.grade}</strong></td>
                  <td>{item.desc}: {item.value}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export default ClassCompositionDetails;

