  });
};

function ClassCompositionDetails({ details }) {
  const { translate } = useWordMappings();

  const { classCountData, otherDetailsData } = useMemo(() => {
    const countKey = Object.keys(details).find(k => k.includes('クラス数'));
    const courseKey = Object.keys(details).find(k => k.includes('文理別コース'));
