    let classCountData = {};
    if (countKey && details[countKey] && typeof details[countKey] === 'string') {
      try { 
        const parsed = JSON.parse(details[countKey]);
        if (parsed && typeof parsed === 'object') classCountData = parsed;
      } catch (e) {}
    }

    const tempOtherData = {};
    const processOtherKey = (key, name) => {
      if (key && details[key] && typeof details[key] === 'string') {
