import React from 'react';

// Heuristic to determine if a string is a sentence rather than a short word/tag.
const isSentence = (str) => {
  if (typeof str !== 'string') return false;
  // Check for common sentence terminators or if the string is long.
  const hasPunctuation = str.includes('。') || str.includes('.');
  const isLong = str.length > 15;
  return hasPunctuation || isLong;
};

const ValueRenderer = ({ value }) => {
  if (value === null || typeof value === 'undefined') {
    return null;
  }

  if (typeof value === 'string' && value.startsWith('[') && value.endsWith(']')) {
    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) {
        // Ensure all items in the array are strings before proceeding
        const allStrings = parsed.every(item => typeof item === 'string');
        if (!allStrings) {
          return <>{String(value)}</>; // Fallback for arrays with non-strings
        }

        // If even one item is a sentence, render the whole thing as a list.
        const isSentenceArray = parsed.some(isSentence);

        if (isSentenceArray) {
          // Render as a list for sentences
          return (
            <ul className="list-unstyled mb-0">
              {parsed.map((item, index) => (
                <li key={index}>{item}</li>
              ))}
            </ul>
          );
        } else {
          // Render as badges for words/tags
          return parsed.map((item, index) => (
            <span key={index} className="badge bg-secondary me-1">
              {item}
            </span>
          ));
        }
      }
    } catch (e) {
      // Fall through to default rendering if JSON parsing fails.
    }
  }

  // Fallback for all other data types or non-array JSON strings.
  return <>{String(value)}</>;
};

export default ValueRenderer;

