import React from 'react';

// Heuristic to determine if a string is a sentence rather than a short word/tag.
const isSentence = (str) => {
  if (typeof str !== 'string') return false;
  const hasPunctuation = str.includes('。') || str.includes('.');
  const isLong = str.length > 15;
  return hasPunctuation || isLong;
};

const ValueRenderer = ({ value }) => {
  // 1. Handle null/undefined/empty values
  if (value === null || value === undefined || value === '') {
    return null;
  }

  // 2. If it's not a string, just render it as a string.
  if (typeof value !== 'string') {
    return <>{String(value)}</>;
  }

  // 3. If it is a string, try to parse it as JSON.
  let parsedValue;
  try {
    // Only parse strings that look like objects or arrays
    if (value.trim().startsWith('{') || value.trim().startsWith('[')) {
      parsedValue = JSON.parse(value);
    } else {
      // It's a plain string, render it directly with line breaks preserved.
      return <p style={{ whiteSpace: 'pre-wrap' }} className="mb-0">{value}</p>;
    }
  } catch (e) {
    // If parsing fails, it's just a plain string.
    return <p style={{ whiteSpace: 'pre-wrap' }} className="mb-0">{value}</p>;
  }

  // 4. Handle the parsed JSON value

  // Handle Arrays
  if (Array.isArray(parsedValue)) {
    const allStrings = parsedValue.every(item => typeof item === 'string');
    if (!allStrings) {
      // If array contains non-strings, render as a simple list
      return (
        <ul className="list-unstyled mb-0">
          {parsedValue.map((item, index) => (
            <li key={index}><ValueRenderer value={item} /></li>
          ))}
        </ul>
      );
    }

    const isSentenceArray = parsedValue.some(isSentence);
    if (isSentenceArray) {
      return (
        <ul className="list-unstyled mb-0">
          {parsedValue.map((item, index) => <li key={index}>{item}</li>)}
        </ul>
      );
    } else {
      return parsedValue.map((item, index) => (
        <span key={index} className="badge bg-secondary me-1">{item}</span>
      ));
    }
  }

  // Handle Objects
  if (parsedValue && typeof parsedValue === 'object') {
    return (
      <ul className="list-group list-group-flush">
        {Object.entries(parsedValue).map(([key, val]) => (
          <li key={key} className="list-group-item px-0 py-1">
            <strong>{key}: </strong>
            {/* Recursive call for nested values */}
            <ValueRenderer value={val} />
          </li>
        ))}
      </ul>
    );
  }

  // Fallback for any other parsed primitives (e.g., a JSON string of just a number)
  return <>{String(parsedValue)}</>;
};

export default ValueRenderer;

import React from 'react';

// Heuristic to determine if a string is a sentence rather than a short word/tag.
const isSentence = (str) => {
  if (typeof str !== 'string') return false;
  const hasPunctuation = str.includes('。') || str.includes('.');
  const isLong = str.length > 15;
  return hasPunctuation || isLong;
};

const ValueRenderer = ({ value }) => {
  // 1. Handle null, undefined, or empty strings
  if (value === null || value === undefined || value === '') {
    return null;
  }

  // 2. Handle strings that might contain JSON
  if (typeof value === 'string') {
    // Only try to parse strings that look like objects or arrays
    if (value.trim().startsWith('{') || value.trim().startsWith('[')) {
      try {
        const parsed = JSON.parse(value);
        // If parsing is successful, recurse with the parsed value.
        // This is the key to handling nested JSON.
        return <ValueRenderer value={parsed} />;
      } catch (e) {
        // Not valid JSON, fall through to render as a plain string.
      }
    }
    // It's just a plain string. Render with preserved line breaks.
    return <p style={{ whiteSpace: 'pre-wrap' }} className="mb-0">{value}</p>;
  }

  // 3. Handle arrays
  if (Array.isArray(value)) {
    // Check if all items are strings to decide on rendering style
    const allStrings = value.every(item => typeof item === 'string');
    if (allStrings) {
      const isSentenceArray = value.some(isSentence);
      if (isSentenceArray) {
        // Render as a simple list for sentences
        return (
          <ul className="list-unstyled mb-0">
            {value.map((item, index) => <li key={index}>{item}</li>)}
          </ul>
        );
      } else {
        // Render as badges for words/tags
        return value.map((item, index) => (
          <span key={index} className="badge bg-secondary me-1">{item}</span>
        ));
      }
    } else {
      // If the array contains mixed or non-string types, render as a list
      // with recursive calls to handle nested objects/arrays.
      return (
        <ul className="list-unstyled mb-0">
          {value.map((item, index) => (
            <li key={index}><ValueRenderer value={item} /></li>
          ))}
        </ul>
      );
    }
  }

  // 4. Handle objects
  if (typeof value === 'object') {
    return (
      <ul className="list-group list-group-flush">
        {Object.entries(value).map(([key, val]) => (
          <li key={key} className="list-group-item px-0 py-1">
            <strong>{key}: </strong>
            {/* Recursive call for nested values */}
            <ValueRenderer value={val} />
          </li>
        ))}
      </ul>
    );
  }

  // 5. Fallback for other primitive types (numbers, booleans)
  return <>{String(value)}</>;
};

