import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

function EducationalContentSection({ details }) {
  const { translate } = useWordMappings();

  const { tableData, otherEntries } = useMemo(() => {
    const typeKey = Object.keys(details).find(k => k.includes('教育内容種別'));
    const descKey = Object.keys(details).find(k => k.includes('教育内容の説明'));

    let types = [];
    let descs = [];

    try {
      if (typeKey && typeof details[typeKey] === 'string') {
        const parsedTypes = JSON.parse(details[typeKey]);
        if (Array.isArray(parsedTypes)) types = parsedTypes;
      }
      if (descKey && typeof details[descKey] === 'string') {
        const parsedDescs = JSON.parse(details[descKey]);
        if (Array.isArray(parsedDescs)) descs = parsedDescs;
      }
    } catch (e) {
      console.error("Failed to parse educational content data:", e);
    }

    // Pair up types and descriptions by index
    const tableData = types.map((type, index) => ({
      id: index,
      type: type,
      description: descs[index] || ''
    }));

    // Filter out the keys that have been handled in the table, plus metadata
    const handledKeys = [typeKey, descKey, 'school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'];
    const otherEntries = Object.entries(details).filter(([key]) => !handledKeys.includes(key));

    return { tableData, otherEntries };
  }, [details]);

  return (
    <div className="mt-3 ps-2">
      {/* Render the 2-column borderless table */}
      {tableData.length > 0 && (
        <table className="table table-borderless" style={{ tableLayout: 'fixed' }}>
          <tbody>
            {tableData.map(item => (
              <tr key={item.id}>
                <td style={{ width: '30%', verticalAlign: 'top' }}><strong>{item.type}</strong></td>
                <td><ValueRenderer value={item.description} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* Render any other details in this topic using the standard text block style */}
      {otherEntries.length > 0 && <hr />}
      {otherEntries.map(([key, value]) => {
        if (!value) return null;
        return (
          <div key={key} className="mb-4">
            <h6 className="fw-bold">{translate(key)}</h6>
            <div className="ps-2">
              <ValueRenderer value={value} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default EducationalContentSection;

