    );
  }

  // Special handling for text-heavy sections like 'educational_policies'
  if (topic === 'educational_policies') {
    return (
      <div className="mb-4">
        <h4 className="p-2 bg-warning rounded">{translate(topic)}</h4>
        <TextBlockSection details={details} />
      </div>
    );
  }

  // Default rendering for all other topics
  return (
    <div className="mb-4">
      <h4 className="p-2 bg-warning rounded">{translate(topic)}</h4>
      <ul className="list-group list-group-flush">
