import React, { useMemo } from 'react';
import ValueRenderer from './ValueRenderer';

function EducationalContentSection({ details }) {

  const { tableData, keys } = useMemo(() => {
    const contentKey = Object.keys(details).find(k => k === 'value_content');
    if (!contentKey || typeof details[contentKey] !== 'string') {
      return { tableData: [], keys: [] };
    }

    try {
      const parsedData = JSON.parse(details[contentKey]);
      if (Array.isArray(parsedData) && parsedData.length > 0) {
        // Dynamically determine the keys from the first object in the array.
        // Assumes all objects in the array share the same structure.
        const dynamicKeys = Object.keys(parsedData[0]);
        return { tableData: parsedData, keys: dynamicKeys };
      }
    } catch (e) {
      console.error("Failed to parse educational content data:", e);
    }

    return { tableData: [], keys: [] };
  }, [details]);

  // Ensure we have the two keys we expect before trying to render.
  if (tableData.length === 0 || keys.length < 2) {
    return null;
  }

  const key1 = keys[0]; // e.g., "教育内容種別" or "方針種別"
  const key2 = keys[1]; // e.g., "教育内容の説明" or "方針内容"

  return (
    <div className="mt-3 ps-2">
      <table className="table table-borderless" style={{ tableLayout: 'auto' }}>
        <tbody>
          {tableData.map((item, index) => (
            <tr key={index}>
              <td style={{ width: '30%', verticalAlign: 'top' }}>
                <strong>{item[key1]}</strong>
              </td>
              <td>
                <ValueRenderer value={item[key2]} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default EducationalContentSection;

