import React, { useMemo } from 'react';
import ValueRenderer from './ValueRenderer';

function SchoolEventsSection({ details }) {

  const groupedEvents = useMemo(() => {
    const contentKey = Object.keys(details).find(k => k === 'value_content');
    if (!contentKey || typeof details[contentKey] !== 'string') {
      return {};
    }

    try {
      const parsedData = JSON.parse(details[contentKey]);
      if (Array.isArray(parsedData)) {
        // Group events by the "行事グループ" key
        const groups = parsedData.reduce((acc, event) => {
          const groupName = event.行事グループ || 'その他';
          if (!acc[groupName]) {
            acc[groupName] = [];
          }
          acc[groupName].push(event);
          return acc;
        }, {});
        return groups;
      }
    } catch (e) {
      console.error("Failed to parse school events data:", e);
    }

    return {};
  }, [details]);

  if (Object.keys(groupedEvents).length === 0) {
    return null;
  }

  return (
    <div className="mt-3 ps-2">
      {Object.entries(groupedEvents).map(([groupName, events]) => (
        <div key={groupName} className="mb-4">
          <h6 className="fw-bold">{groupName}</h6>
          <div className="table-responsive">
            <table className="table table-striped">
              <thead className="table-light">
                <tr>
                  <th style={{width: '15%'}}>学年</th>
                  <th style={{width: '25%'}}>種別</th>
                  <th>内容</th>
                </tr>
              </thead>
              <tbody>
                {events.map((event, index) => (
                  <tr key={index}>
                    <td>{event.学年}</td>
                    <td>{event.種別}</td>
                    <td><ValueRenderer value={event.内容} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ))}
    </div>
  );
}

export default SchoolEventsSection;

