import React from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

function SchoolEventsSection({ details }) {
  const { translate } = useWordMappings();

  // Filter out metadata keys before rendering
  const eventGroupEntries = Object.entries(details).filter(([key]) => 
    !['school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'].includes(key)
  );

  if (eventGroupEntries.length === 0) {
    return null;
  }

  return (
    <div className="mt-3 ps-2">
      {eventGroupEntries.map(([key, value]) => {
        let parsedData;
        try {
          if (typeof value === 'string' && (value.trim().startsWith('[') || value.trim().startsWith('{'))) {
            parsedData = JSON.parse(value);
          } else {
            // If it's a simple string, just render it directly.
            return (
              <div key={key} className="mb-4">
                <h6 className="fw-bold">{translate(key)}</h6>
                <ValueRenderer value={value} />
              </div>
            );
          }
        } catch (e) {
          // If parsing fails, render the original string.
          return (
            <div key={key} className="mb-4">
              <h6 className="fw-bold">{translate(key)}</h6>
              <ValueRenderer value={value} />
            </div>
          );
        }

        // Check if the parsed data is an array of objects suitable for the events table
        if (Array.isArray(parsedData) && parsedData.length > 0 && typeof parsedData[0] === 'object' && (parsedData[0].種別 || parsedData[0].内容)) {
