import React, { useMemo } from 'react';

// Helper to sort grade keys like 中1, 中2, ..., 高1, 高2, ...
const sortGradeKeys = (gradeKeys) => {
  return gradeKeys.sort((a, b) => {
    const isAHs = a.startsWith('高');
    const isBHs = b.startsWith('高');
    const numA = parseInt(a.replace(/[^0-9]/g, ''), 10) || 0;
    const numB = parseInt(b.replace(/[^0-9]/g, ''), 10) || 0;

    if (isAHs && !isBHs) return 1;
    if (!isAHs && isBHs) return -1;
    return numA - numB;
  });
};

function SubjectHoursTable({ data }) { // data is the unpivoted array
  const { grades, subjects, pivotedData } = useMemo(() => {
    if (!Array.isArray(data) || data.length === 0) {
      return { grades: [], subjects: [], pivotedData: {} };
    }

    // Pivot the data: from [{grade, subject, hours}, ...] to { grade: { subject: hours } }
    const pivoted = data.reduce((acc, item) => {
      const grade = item.学年;
      const subject = item.教科;
      const hours = item.週当たり授業時間数;

      if (!acc[grade]) {
        acc[grade] = {};
      }
      acc[grade][subject] = hours;
      return acc;
    }, {});

    const allGrades = Object.keys(pivoted);
    sortGradeKeys(allGrades);

    // Get a unique, sorted list of all subjects mentioned
    const allSubjects = Array.from(new Set(data.map(item => item.教科))).sort();

    return { grades: allGrades, subjects: allSubjects, pivotedData: pivoted };
  }, [data]);

  if (grades.length === 0) return null;

  return (
    <div className="table-responsive">
      <table className="table table-bordered table-striped text-center">
        <thead className="table-light">
          <tr>
            <th>学年</th>
            {subjects.map(subject => <th key={subject}>{subject}</th>)}
          </tr>
        </thead>
        <tbody>
          {grades.map(grade => (
            <tr key={grade}>
              <td>{grade}</td>
              {subjects.map(subject => (
                <td key={subject}>{pivotedData[grade]?.[subject] ?? '-'}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default SubjectHoursTable;

