import React, { useMemo } from 'react';

// Helper to sort grade keys like 中1, 中2, ..., 高1, 高2, ...
const sortGradeKeys = (gradeKeys) => {
  return gradeKeys.sort((a, b) => {
    const isAHs = a.startsWith('高');
    const isBHs = b.startsWith('高');
    const numA = parseInt(a.replace(/[^0-9]/g, ''), 10) || 0;
    const numB = parseInt(b.replace(/[^0-9]/g, ''), 10) || 0;

    if (isAHs && !isBHs) return 1;
    if (!isAHs && isBHs) return -1;
    return numA - numB;
  });
};

function SubjectHoursTable({ data }) {
  const { grades, subjects, pivotedData, rowTotals, columnTotals, grandTotal } = useMemo(() => {
    if (!Array.isArray(data) || data.length === 0) {
      return { grades: [], subjects: [], pivotedData: {}, rowTotals: {}, columnTotals: {}, grandTotal: 0 };
    }

    const pivoted = data.reduce((acc, item) => {
      const grade = item.学年;
      const subject = item.教科;
      const hours = parseInt(item.週当たり授業時間数, 10) || 0;

      if (grade && subject) {
        if (!acc[grade]) acc[grade] = {};
        acc[grade][subject] = hours;
      }
      return acc;
    }, {});

    const allGrades = Object.keys(pivoted);
    sortGradeKeys(allGrades);

    const allSubjects = Array.from(new Set(data.map(item => item.教科))).sort();

    // Calculate totals
    const rowTotals = {};
    allSubjects.forEach(subject => {
      rowTotals[subject] = allGrades.reduce((sum, grade) => sum + (pivoted[grade]?.[subject] || 0), 0);
    });

    const columnTotals = {};
    allGrades.forEach(grade => {
      columnTotals[grade] = allSubjects.reduce((sum, subject) => sum + (pivoted[grade]?.[subject] || 0), 0);
    });

    const grandTotal = Object.values(columnTotals).reduce((sum, total) => sum + total, 0);

    return { grades: allGrades, subjects: allSubjects, pivotedData: pivoted, rowTotals, columnTotals, grandTotal };
  }, [data]);

  if (subjects.length === 0) return null;

  return (
    <div className="table-responsive">
      <table className="table table-bordered table-striped text-center">
        <thead className="table-light">
          <tr>
            <th>教科</th>
            {grades.map(grade => <th key={grade}>{grade}</th>)}
            <th className="fw-bold">合計</th>
          </tr>
        </thead>
        <tbody>
          {subjects.map(subject => (
            <tr key={subject}>
              <td>{subject}</td>
              {grades.map(grade => (
                <td key={grade}>{pivotedData[grade]?.[subject] || '-'}</td>
              ))}
              <td className="fw-bold">{rowTotals[subject] || '-'}</td>
            </tr>
          ))}
          <tr className="table-light fw-bold">
            <td>合計</td>
            {grades.map(grade => (
              <td key={grade}>{columnTotals[grade] || '-'}</td>
            ))}
            <td>{grandTotal || '-'}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

