import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

// Helper to sort grade keys like 中1, 中2, ..., 高1, 高2, ...
const sortGrades = (array, gradeField) => {
  array.sort((a, b) => {
    const gradeA = a[gradeField] || '';
    const gradeB = b[gradeField] || '';
    const isAHs = gradeA.startsWith('高');
    const isBHs = gradeB.startsWith('高');
    const numA = parseInt(gradeA.replace(/[^0-9]/g, ''), 10) || 0;
    const numB = parseInt(gradeB.replace(/[^0-9]/g, ''), 10) || 0;

    if (isAHs && !isBHs) return 1;
    if (!isAHs && isBHs) return -1;
    return numA - numB;
  });
};

function ClassCompositionDetails({ details }) {
  const { translate } = useWordMappings();

  const { classCountData, otherDetailsData } = useMemo(() => {
    let classCountData = [];
    const otherDetailsData = [];

    for (const [key, value] of Object.entries(details)) {
      if (typeof value !== 'string' || !value.startsWith('[')) {
        continue; // Skip non-array-string values
      }

      try {
        const parsedArray = JSON.parse(value);
        if (!Array.isArray(parsedArray)) continue;

        if (key.includes('クラス数')) {
          classCountData = parsedArray;
        } else if (key.includes('文理別コース') || key.includes('1クラスあたりの人数') || key.includes('その他コース')) {
          parsedArray.forEach(item => {
            if (item && typeof item === 'object' && item.学年) {
              // Dynamically find the other key in the object that is not '学年'
              const valueKey = Object.keys(item).find(k => k !== '学年');
              if (valueKey && item[valueKey]) {
                otherDetailsData.push({
                  id: `${item.学年}-${key}`,
                  grade: item.学年,
                  description: translate(key),
                  value: item[valueKey],
                });
              }
            }
          });
        }
      } catch (e) {
        console.error(`Failed to parse details for key: ${key}`, e);
      }
    }

    sortGrades(classCountData, '学年');
    sortGrades(otherDetailsData, 'grade');

    return { classCountData, otherDetailsData };
  }, [details, translate]);

  return (
    <div>
      {/* Table 1: Class Counts */}
      {classCountData.length > 0 && (
        <div className="mb-4">
          <div className="table-responsive">
            <table className="table table-bordered text-center">
              <thead>
                <tr>
                  {classCountData.map(item => <th key={item.学年}>{item.学年}</th>)}
                </tr>
              </thead>
              <tbody>
                <tr>
                  {classCountData.map(item => <td key={item.学年}>{item.クラス数 ? `${item.クラス数}クラス` : '-'}</td>)}
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Table 2: Other Details (borderless) */}
      {otherDetailsData.length > 0 && (
        <div className="mb-4">
          <table className="table" style={{ tableLayout: 'fixed' }}>
            <tbody>
              {otherDetailsData.map(item => (
                <tr key={item.id}>
                  <td style={{ width: '25%' }}><strong>{item.grade}</strong></td>
                  <td>
                    <ValueRenderer value={item.value} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export default ClassCompositionDetails;

import React from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

function SchoolEventsSection({ details }) {
  const { translate } = useWordMappings();

  // Filter out metadata keys before rendering
