            <div key={key} className="mb-4">
              <h6 className="fw-bold">{translate(key)}</h6>
              <ValueRenderer value={value} />
            </div>
          );
        }

        // Check if the parsed data is an array of objects suitable for the events table
        if (Array.isArray(parsedData) && parsedData.length > 0 && typeof parsedData[0] === 'object' && (parsedData[0].種別 || parsedData[0].内容)) {
          return (
            <div key={key} className="mb-4">
              <h6 className="fw-bold">{translate(key)}</h6>
              <div className="table-responsive">
                <table className="table table-striped" style={{ tableLayout: 'auto' }}>
                  <thead className="table-light">
                    <tr>
                      <th style={{width: '15%'}}>学年</th>
                      <th style={{width: '25%'}}>種別</th>
                      <th>内容</th>
                    </tr>
                  </thead>
                  <tbody>
                    {parsedData.map((event, index) => (
                      <tr key={index}>
                        <td>{event.学年 || '全学年'}</td>
                        <td>{event.種別 || '-'}</td>
                        <td><ValueRenderer value={event.内容} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          );
        }

        // Fallback for other data structures (e.g., an array of strings for 国際交流)
        return (
          <div key={key} className="mb-4">
            <h6 className="fw-bold">{translate(key)}</h6>
            <ValueRenderer value={value} />
          </div>
        );
      })}
    </div>
  );
}

export default SchoolEventsSection;

