import React, { createContext, useState, useEffect, useContext } from 'react';

const API_BASE_URL = 'http://127.0.0.1:8000';

const WordMappingContext = createContext();

export function useWordMappings() {
  return useContext(WordMappingContext);
}

export function WordMappingProvider({ children }) {
  const [mappings, setMappings] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [language, setLanguage] = useState('ja'); // Default language

  useEffect(() => {
    const fetchMappings = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/words`);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setMappings(data || {});
      } catch (e) {
        setError(e);
        console.error("Failed to fetch word mappings:", e);
      } finally {
        setLoading(false);
      }
    };

    fetchMappings();
  }, []);

  const translate = (key) => {
    if (!key) return '';

    // First, check for a direct translation in the mappings
    if (mappings[key] && mappings[key][language]) {
      return mappings[key][language];
    }

    let cleanKey = key;
    // If no mapping, clean up any 'unmapped' markers from the key itself
    if (typeof key === 'string') {
      cleanKey = key.replace(/unmapped_ja_/g, ''); // Remove all occurrences
    }

    // Default fallback with the cleaned key
    return cleanKey.replace(/_/g, ' ');
  };

  const value = {
    mappings,
    loading,
    error,
    language,
    setLanguage,
    translate,
  };

  return (
    <WordMappingContext.Provider value={value}>
      {!loading && children}
    </WordMappingContext.Provider>
  );
}

