import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

function AcceptanceRecordSection({ details }) {
  const { translate } = useWordMappings();

  const { groupedDataByYear, otherEntries } = useMemo(() => {
    const tableKey = Object.keys(details).find(k => k.includes('合格実績'));

    let records = [];
    if (tableKey && typeof details[tableKey] === 'string') {
      try {
        const parsed = JSON.parse(details[tableKey]);
        if (Array.isArray(parsed)) {
          records = parsed;
        }
      } catch(e) {
        console.error("Failed to parse acceptance record data:", e);
      }
    }

    // 1. Group all records by year ("年度")
    const groupedByYearRaw = records.reduce((acc, record) => {
      const year = record.年度 || '不明';
      if (!acc[year]) {
        acc[year] = [];
      }
      acc[year].push(record);
      return acc;
    }, {});

    // 2. For each year, pivot the data by university
    const pivotedDataByYear = {};
    for (const year in groupedByYearRaw) {
      const yearRecords = groupedByYearRaw[year];

      const uniData = yearRecords.reduce((acc, record) => {
        const uniName = record.大学名;
        const count = parseInt(record.人数, 10) || 0;

        if (!acc[uniName]) {
          acc[uniName] = { uniName: uniName, 現役: 0, 浪人: 0 };
        }

        if (record.属性 === '現役') {
          acc[uniName].現役 += count;
        } else {
          // Assume anything not '現役' is '浪人' for calculation purposes
          acc[uniName].浪人 += count;
        }
        return acc;
      }, {});

      // Calculate the total ("浪人含む") and convert to a sorted array
      const finalUniData = Object.values(uniData).map(uni => ({
        ...uni,
        浪人含む: uni.現役 + uni.浪人,
      })).sort((a, b) => b.浪人含む - a.浪人含む); // Sort by total acceptances

      pivotedDataByYear[year] = finalUniData;
    }

    const handledKeys = [tableKey, 'school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'];
    const otherEntries = Object.entries(details).filter(([key]) => !handledKeys.includes(key));

    return { groupedDataByYear: pivotedDataByYear, otherEntries };
  }, [details]);

  // Sort years in descending order
  const sortedYears = Object.keys(groupedDataByYear).sort((a, b) => b - a);

  return (
    <div className="mt-3 ps-2">
      {/* Render a table for each year */}
      {sortedYears.map(year => (
        <div key={year} className="mb-5">
          <h3 className="fw-bold">{`${year}年度 合格実績`}</h3>
          <div className="table-responsive">
            <table className="table table-striped table-bordered">
              <thead className="table-light">
                <tr>
                  <th>大学名</th>
                  <th className="text-center">現役</th>
                  <th className="text-center">浪人含む</th>
                </tr>
              </thead>
              <tbody>
                {groupedDataByYear[year].map((record) => (
                  <tr key={record.uniName}>
                    <td>{record.uniName}</td>
                    <td className="text-center">{record.現役 || '-'}</td>
                    <td className="text-center">{record.浪人含む || '-'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ))}

      {/* Render other details from the same topic */}
      {otherEntries.length > 0 && <hr />}
      {otherEntries.map(([key, value]) => {
        if (!value) return null;
        return (
          <div key={key} className="mb-4">
            <h3 className="fw-bold">{translate(key)}</h3>
            <div className="ps-2">
              <ValueRenderer value={value} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default AcceptanceRecordSection;

