import ValueRenderer from './ValueRenderer';

function CareersSection({ details }) {
  const { translate } = useWordMappings();

  const { acceptanceData, recommendationData, otherEntries } = useMemo(() => {
    const acceptanceKey = Object.keys(details).find(k => k.includes('合格実績'));
    const recommendationKey = Object.keys(details).find(k => k.includes('指定校推薦枠'));

    // --- 1. Process Acceptance Records ---
    let acceptanceRecords = [];
    if (acceptanceKey && typeof details[acceptanceKey] === 'string') {
      try {
        const parsed = JSON.parse(details[acceptanceKey]);
        if (Array.isArray(parsed)) acceptanceRecords = parsed;
      } catch(e) { console.error("Failed to parse acceptance record data:", e); }
    }

    const groupedAcceptance = acceptanceRecords.reduce((acc, record) => {
      const year = record.年度 || '不明';
      if (!acc[year]) acc[year] = [];
      acc[year].push(record);
      return acc;
    }, {});

    const pivotedAcceptance = {};
    for (const year in groupedAcceptance) {
      const yearRecords = groupedAcceptance[year];
      const uniData = yearRecords.reduce((acc, record) => {
        const uniName = record.大学名;
        const count = parseInt(record.人数, 10) || 0;
        if (!acc[uniName]) acc[uniName] = { uniName, 現役: 0, 浪人: 0 };
        if (record.属性 === '現役') acc[uniName].現役 += count; else acc[uniName].浪人 += count;
        return acc;
      }, {});
      pivotedAcceptance[year] = Object.values(uniData)
        .map(uni => ({ ...uni, 浪人含む: uni.現役 + uni.浪人 }))
        .sort((a, b) => b.浪人含む - a.浪人含む);
    }

    // --- 2. Process Recommendation Records ---
    let recommendationRecords = [];
    if (recommendationKey && typeof details[recommendationKey] === 'string') {
      try {
        const parsed = JSON.parse(details[recommendationKey]);
        if (Array.isArray(parsed)) recommendationRecords = parsed;
      } catch(e) { console.error("Failed to parse recommendation data:", e); }
    }

    const groupedRecommendation = recommendationRecords.reduce((acc, record) => {
      const year = record.年度 || '不明';
      if (!acc[year]) acc[year] = [];
      acc[year].push(record);
      return acc;
    }, {});

    const handledKeys = [acceptanceKey, recommendationKey, 'school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'];
    const otherEntries = Object.entries(details).filter(([key]) => !handledKeys.includes(key));

    return { acceptanceData: pivotedAcceptance, recommendationData: groupedRecommendation, otherEntries };
  }, [details]);

  const sortedAcceptanceYears = Object.keys(acceptanceData).sort((a, b) => b - a);
  const sortedRecommendationYears = Object.keys(recommendationData).sort((a, b) => b - a);

  return (
    <div className="mt-3 ps-2">
      {/* Render Acceptance Record tables */}
      {sortedAcceptanceYears.map(year => (
