import React from 'react';
import { Pie } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, Tooltip, Legend, Title } from 'chart.js';
import ChartDataLabels from 'chartjs-plugin-datalabels';

ChartJS.register(ArcElement, Tooltip, Legend, Title, ChartDataLabels);

// Helper to generate a set of distinct colors for chart slices
const generateColors = (numColors) => {
  const colors = [];
  const baseColors = [
    [54, 162, 235],  // Blue
    [255, 99, 132],  // Pink
    [75, 192, 192],  // Green
    [255, 206, 86],  // Yellow
    [153, 102, 255], // Purple
    [255, 159, 64],  // Orange
    [99, 255, 132],   // Lime
    [201, 203, 207]  // Grey
  ];
  for (let i = 0; i < numColors; i++) {
    const color = baseColors[i % baseColors.length];
    colors.push(`rgba(${color[0]}, ${color[1]}, ${color[2]}, 0.6)`);
  }
  return colors;
};

const CustomPieChart = ({ chartData, title }) => {
  if (!chartData || !chartData.labels || !chartData.values || chartData.values.reduce((a, b) => a + b, 0) === 0) {
     return <div className="text-center p-4"><strong>{title}</strong><br/>データがありません</div>;
  }

  const data = {
    labels: chartData.labels,
    datasets: [
      {
        data: chartData.values,
        backgroundColor: generateColors(chartData.labels.length),
        borderWidth: 1,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: true,
    plugins: {
      legend: {
        display: true,
        position: 'right',
      },
      title: {
        display: true,
        text: title,
        font: { size: 16 }
      },
      datalabels: {
        formatter: (value, ctx) => {
          const total = ctx.chart.data.datasets[0].data.reduce((a, b) => a + b, 0);
          if (total === 0) return '0%';
          const percentage = ((value / total) * 100);
          // Don't show percentage for very small slices
          return percentage > 5 ? percentage.toFixed(1) + '%' : '';
        },
        color: '#fff',
        font: {
          weight: 'bold',
        },
      },
    },
  };

  return <Pie data={data} options={options} />;
};

export default CustomPieChart;

