import { useState, useMemo } from 'react';

export const useSortableData = (items, config = null) => {
  const [sortConfig, setSortConfig] = useState(config);

  const sortedItems = useMemo(() => {
    if (!items) {
      return [];
    }
    let sortableItems = [...items];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];

        // Handle numeric sorting
        if (typeof valA === 'number' && typeof valB === 'number') {
          if (valA < valB) {
            return sortConfig.direction === 'ascending' ? -1 : 1;
          }
          if (valA > valB) {
            return sortConfig.direction === 'ascending' ? 1 : -1;
          }
          return 0;
        }

        // Handle string sorting
        const strA = String(valA || '');
        const strB = String(valB || '');

        if (strA.localeCompare(strB, 'ja') < 0) {
          return sortConfig.direction === 'ascending' ? -1 : 1;
        }
        if (strA.localeCompare(strB, 'ja') > 0) {
          return sortConfig.direction === 'ascending' ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [items, sortConfig]);

  const requestSort = (key) => {
    let direction = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  return { items: sortedItems, requestSort, sortConfig };
};

import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';
import CustomPieChart from './CustomPieChart';
import { useSortableData } from '../hooks/useSortableData';

// Reusable component for sortable table headers
const SortableTh = ({ children, requestSort, sortConfig, sortKey }) => {
  const getSortDirectionIndicator = () => {
    if (!sortConfig || sortConfig.key !== sortKey) {
      return null;
    }
    return sortConfig.direction === 'ascending' ? ' ▲' : ' ▼';
  };

  return (
    <th className="text-center" onClick={() => requestSort(sortKey)} style={{ cursor: 'pointer' }}>
      {children}{getSortDirectionIndicator()}
    </th>
  );
};

// Sortable table for Recommendation Records
const RecommendationTable = ({ records }) => {
  const { items, requestSort, sortConfig } = useSortableData(records);

  return (
    <div className="table-responsive">
