            <tr key={index}><td>{record.大学名}</td><td className="text-center">{record.枠数 ?? '-'}</td></tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

// Sortable table for Acceptance Records
const AcceptanceTable = ({ records }) => {
  const { items, requestSort, sortConfig } = useSortableData(records, { key: '浪人含む', direction: 'descending' });

  return (
    <div className="table-responsive">
      <table className="table table-striped table-bordered">
