          ))}
        </tbody>
      </table>
    </div>
  );
};

function CareersSection({ details }) {
  const { translate } = useWordMappings();

  const { acceptanceData, recommendationData, facultyPieData, otherEntries } = useMemo(() => {
    const acceptanceKey = Object.keys(details).find(k => k.includes('合格実績') && details[k]);
    const recommendationKey = Object.keys(details).find(k => k.includes('指定校推薦枠') && details[k]);
    const facultyPieKey = Object.keys(details).find(k => k.includes('進学先学部割合') && details[k]);

    let acceptanceData = {};
    if (acceptanceKey && typeof details[acceptanceKey] === 'string') {
      try {
        const parsed = JSON.parse(details[acceptanceKey]);
        if (Array.isArray(parsed)) {
          const grouped = parsed.reduce((acc, r) => ({ ...acc, [r.年度 || '不明']: [...(acc[r.年度 || '不明'] || []), r] }), {});
          for (const year in grouped) {
            const uniData = grouped[year].reduce((acc, r) => {
              const name = r.大学名; const count = parseInt(r.人数, 10) || 0;
              if (!acc[name]) acc[name] = { uniName: name, 現役: 0, 浪人: 0 };
              if (r.属性 === '現役') acc[name].現役 += count; else acc[name].浪人 += count;
              return acc;
            }, {});
            acceptanceData[year] = Object.values(uniData).map(u => ({ ...u, 浪人含む: u.現役 + u.浪人 }));
          }
        }
      } catch(e) { console.error("Failed to parse acceptance record data:", e); }
    }

    let recommendationData = {};
    if (recommendationKey && typeof details[recommendationKey] === 'string') {
      try {
        const parsed = JSON.parse(details[recommendationKey]);
        if (Array.isArray(parsed)) {
          recommendationData = parsed.reduce((acc, r) => ({ ...acc, [r.年度 || '不明']: [...(acc[r.年度 || '不明'] || []), r] }), {});
        }
      } catch(e) { console.error("Failed to parse recommendation data:", e); }
    }

    let facultyPieData = null;
    if (facultyPieKey && typeof details[facultyPieKey] === 'string') {
      try {
        const parsed = JSON.parse(details[facultyPieKey]);
        if (Array.isArray(parsed)) {
          facultyPieData = { labels: parsed.map(p => p.学部), values: parsed.map(p => p.割合 || 0) };
        }
      } catch(e) { console.error("Failed to parse faculty pie data:", e); }
    }

    const handledKeys = [acceptanceKey, recommendationKey, facultyPieKey, 'school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'];
    const otherEntries = Object.entries(details).filter(([key]) => !handledKeys.includes(key));

    return { acceptanceData, recommendationData, facultyPieData, otherEntries };
  }, [details]);

  const sortedAcceptanceYears = Object.keys(acceptanceData).sort((a, b) => b - a);
  const sortedRecommendationYears = Object.keys(recommendationData).sort((a, b) => b - a);

  return (
    <div className="mt-3 ps-2">
      {otherEntries.map(([key, value]) => {
        if (!value) return null;
        let displayValue;
        if (key.includes('併設大学への進学割合')) {
          displayValue = `${value}%`;
        } else {
          displayValue = <ValueRenderer value={value} />;
        }
        return (
          <div key={key} className="mb-4">
            <h3 className="fw-bold">{translate(key)}</h3>
            <div className="ps-2">{displayValue}</div>
          </div>
        );
      })}
      {(otherEntries.length > 0 && (sortedAcceptanceYears.length > 0 || sortedRecommendationYears.length > 0 || facultyPieData)) && <hr />}

      {facultyPieData && (
        <div className="mb-5 mx-auto" style={{maxWidth: '500px'}}>
           <CustomPieChart chartData={facultyPieData} title="現役大学進学者の進路内訳" />
        </div>
      )}

      {sortedRecommendationYears.map(year => (
        <div key={`recommend-${year}`} className="mb-5">
          <h3 className="fw-bold">{`${year}年度 指定校推薦枠`}</h3>
          <RecommendationTable records={recommendationData[year]} />
        </div>
      ))}

      {sortedAcceptanceYears.length > 0 && (
        <div className="mb-5">
          <h3 className="fw-bold">合格実績</h3>
          <ul className="nav nav-tabs" id="acceptanceTab" role="tablist">
            {sortedAcceptanceYears.map((year, index) => (
              <li className="nav-item" role="presentation" key={`${year}-tab-btn`}>
                <button className={`nav-link ${index === 0 ? 'active' : ''}`} id={`${year}-tab`} data-bs-toggle="tab" data-bs-target={`#tab-pane-${year}`} type="button" role="tab" aria-controls={`tab-pane-${year}`} aria-selected={index === 0}>
                  {`${year}年度`}
                </button>
              </li>
            ))}
          </ul>
          <div className="tab-content border border-top-0 p-3" id="acceptanceTabContent">
            {sortedAcceptanceYears.map((year, index) => (
              <div className={`tab-pane fade ${index === 0 ? 'show active' : ''}`} id={`tab-pane-${year}`} role="tabpanel" aria-labelledby={`${year}-tab`} key={`${year}-tab-pane`}>
                <AcceptanceTable records={acceptanceData[year]} />
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default CareersSection;

