import React from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';
import StudentCountTable from './StudentCountTable';
import ClassCompositionDetails from './ClassCompositionDetails';
import TextBlockSection from './TextBlockSection';
import EducationalContentSection from './EducationalContentSection';
import SchoolEventsSection from './SchoolEventsSection';
import CurriculumSection from './CurriculumSection';
import AcceptanceRecordSection from './CareersSection';
import AdmissionsSection from './AdmissionsSection';

function TopicSection({ topic, details, classesDetails }) { // Accept classesDetails prop
  const { translate } = useWordMappings();

  if (!details) {
    return null;
  }

  // Merged Students and Classes section
  if (topic === 'students') {
    const studentCountKey = Object.keys(details).find(k => k.includes('生徒数') && !k.includes('総生徒数'));

    let studentCountData = null;
    if (studentCountKey && typeof details[studentCountKey] === 'string') {
      try {
        const parsed = JSON.parse(details[studentCountKey]);
        if (Array.isArray(parsed)) {
          studentCountData = parsed;
        }
      } catch (e) {
        console.error("Could not parse student count data:", e);
      }
    }

    const otherDetailEntries = Object.entries(details).filter(([key]) => 
      key !== studentCountKey && !['school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'].includes(key)
    );

    return (
      <div className="mb-4">
        <h2 className="p-2 bg-warning rounded">{translate(topic)}</h2>

        {studentCountData ? (
          <StudentCountTable studentCountData={studentCountData} />
        ) : (
          <p>{translate('no_student_count_data')}</p>
        )}

        {otherDetailEntries.length > 0 && <h3 className="mt-4">{translate('other_information')}</h3>}
        <ul className="list-group list-group-flush">
          {otherDetailEntries.map(([key, value]) => {
            if ((key.includes('併設小学校からの内部進学率') || key.includes('生徒の特徴')) && !value) {
              return null;
            }
            let displayValue;
            if (key.includes('中高総生徒数')) {
              const num = parseInt(value, 10);
              displayValue = isNaN(num) ? value : `${num.toLocaleString()}名`;
            } else if (key.includes('併設小学校からの内部進学率')) {
              displayValue = `${value}%`;
            } else {
              displayValue = <ValueRenderer value={value} />;
            }
            return (
              <li key={key} className="list-group-item d-flex flex-wrap align-items-center">
                <strong className="text-capitalize col-12 col-md-3">{translate(key)}:</strong>
                <div className="ms-2 col-12 col-md-8">{displayValue}</div>
              </li>
            );
          })}
        </ul>

        {classesDetails && (
          <div className="mt-4">
            <h2 className="p-2 bg-warning rounded">{translate('classes')}</h2>
            <ClassCompositionDetails details={classesDetails} />
          </div>
        )}
      </div>
    );
  }

  // Special handling for content-heavy sections that use the 2-column table format
  if (topic === 'educational_contents' || topic === 'educational_policies') {
    return (
      <div className="mb-4">
        <h2 className="p-2 bg-warning rounded">{translate(topic)}</h2>
        <EducationalContentSection details={details} />
      </div>
    );
  }

  // Special handling for 'school_events'
  if (topic === 'school_events') {
    return (
      <div className="mb-4">
        <h2 className="p-2 bg-warning rounded">{translate(topic)}</h2>
        <SchoolEventsSection details={details} />
      </div>
    );
  }

  // Special handling for 'curriculums'
  if (topic === 'curriculums') {
    return (
      <div className="mb-4">
        <h2 className="p-2 bg-warning rounded">{translate(topic)}</h2>
        <CurriculumSection details={details} />
      </div>
    );
  }

  // Special handling for 'careers' (shinro)
  if (topic === 'careers') {
    return (
      <div className="mb-4">
        <h2 className="p-2 bg-warning rounded">{translate(topic)}</h2>
        <CareersSection details={details} />
      </div>
    );
  }

  // Special handling for 'admission'
  if (topic === 'admission') {
    return (
      <div className="mb-4">
        <h2 className="p-2 bg-warning rounded">{translate(topic)}</h2>
        <AdmissionsSection details={details} />
      </div>
    );
  }

  // Default rendering for all other topics
  return (
    <div className="mb-4">
      <h2 className="p-2 bg-warning rounded">{translate(topic)}</h2>
      <ul className="list-group list-group-flush">
        {Object.entries(details).map(([key, value]) => {
          if (['school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'].includes(key)) {
            return null;
          }
          return (
            <li key={key} className="list-group-item d-flex flex-wrap align-items-center">
              <strong className="text-capitalize col-12 col-md-3">{translate(key)}:</strong>
              <div className="ms-2 col-12 col-md-8">
                <ValueRenderer value={value} />
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export default TopicSection;

