import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

function AdmissionsSection({ details }) {
  const { translate } = useWordMappings();

  const { groupedByYear, otherEntries } = useMemo(() => {
    const guidelinesKey = Object.keys(details).find(k => k.includes('募集要項') && details[k]);

    let records = [];
    if (guidelinesKey && typeof details[guidelinesKey] === 'string') {
      try {
        const parsed = JSON.parse(details[guidelinesKey]);
        if (Array.isArray(parsed)) records = parsed;
      } catch(e) { console.error("Failed to parse admissions guidelines data:", e); }
    }

    // 1. Group all records by year ("年度")
    const groupedByYearRaw = records.reduce((acc, record) => {
      const year = record.年度 || '不明';
      if (!acc[year]) acc[year] = [];
      acc[year].push(record);
      return acc;
    }, {});

    // 2. For each year, pivot the data by date and type
    const finalGroupedData = {};
    for (const year in groupedByYearRaw) {
      const yearRecords = groupedByYearRaw[year];
      const dates = [...new Set(yearRecords.map(r => r.入試日))].sort();
      const types = [...new Set(yearRecords.map(r => r.入試種別))];

      const pivotedData = yearRecords.reduce((acc, record) => {
        const { 入試日, 入試種別 } = record;
        if (!acc[入試日]) acc[入試日] = {};
        acc[入試日][入試種別] = true; // Mark the exam's existence
        return acc;
      }, {});

      finalGroupedData[year] = { dates, types, pivotedData };
    }

    const handledKeys = [guidelinesKey, 'school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'];
    const otherEntries = Object.entries(details).filter(([key]) => !handledKeys.includes(key));

    return { groupedByYear: finalGroupedData, otherEntries };
  }, [details]);

  const sortedYears = Object.keys(groupedByYear).sort((a, b) => b - a);

  return (
    <div className="mt-3 ps-2">
      {/* Render the pivoted table for application guidelines */}
      {sortedYears.map(year => {
        const { dates, types, pivotedData } = groupedByYear[year];
        return (
          <div key={year} className="mb-4">
            <h3 className="fw-bold">{`${year}年度 募集要項`}</h3>
            <div className="table-responsive">
              <table className="table table-bordered table-striped">
                <thead className="table-light">
                  <tr>
                    <th className="text-center">入試日</th>
                    {types.map(type => <th key={type} className="text-center">{type}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {dates.map(date => (
                    <tr key={date}>
                      <td className="text-center">{date}</td>
                      {types.map(type => (
                        <td key={type} className="text-center">
                          {pivotedData[date]?.[type] ? '●' : ''}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      })}

      {/* Render other details from the same topic */}
      {otherEntries.length > 0 && <hr />}
      {otherEntries.map(([key, value]) => {
        if (!value) return null;
        return (
          <div key={key} className="mb-4">
            <h3 className="fw-bold">{key.replace(/unmapped_ja_/g, '').replace(/_/g, ' ')}</h3>
            <div className="ps-2"><ValueRenderer value={value} /></div>
          </div>
        );
      })}
    </div>
  );
}

export default AdmissionsSection;

