import React, { useMemo } from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

function AdmissionsSection({ details }) {
  const { translate } = useWordMappings();

  const { yearlyGuidelines, otherEntries } = useMemo(() => {
    const guidelinesKey = Object.keys(details).find(k => k.includes('募集要項') && details[k]);

    let records = [];
    if (guidelinesKey && typeof details[guidelinesKey] === 'string') {
      try {
        const parsed = JSON.parse(details[guidelinesKey]);
        if (Array.isArray(parsed)) records = parsed;
      } catch(e) { console.error("Failed to parse admissions guidelines data:", e); }
    }

    const groupedByYear = records.reduce((acc, record) => {
      const year = record.年度 || '不明';
      if (!acc[year]) acc[year] = [];
      acc[year].push(record);
      return acc;
    }, {});

    const handledKeys = [guidelinesKey, 'school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'];
    const otherEntries = Object.entries(details).filter(([key]) => !handledKeys.includes(key));

    return { yearlyGuidelines: groupedByYear, otherEntries };
  }, [details]);

  const sortedYears = Object.keys(yearlyGuidelines).sort((a, b) => b - a);

  return (
    <div className="mt-3 ps-2">
      {sortedYears.map(year => {
        const yearRecords = yearlyGuidelines[year];
        if (!yearRecords || yearRecords.length === 0) return null;

        const mainHeaders = Array.from(new Set(yearRecords.flatMap(r => Object.keys(r))))
                               .filter(key => key !== '年度' && key !== '試験内容');

        return (
          <div key={year} className="mb-5">
            <h3 className="fw-bold">{`${year}年度 募集要項`}</h3>
            <div className="table-responsive">
              <table className="table table-striped table-bordered">
                <thead className="table-light">
                  <tr>
                    {mainHeaders.map(h => <th key={h}>{h}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {yearRecords.map((record, index) => (
                    <React.Fragment key={index}>
                      {/* Main Row */}
                      <tr>
                        {mainHeaders.map(header => (
                          <td key={header}>
                            <ValueRenderer value={record[header]} />
                          </td>
                        ))}
                      </tr>
                      {/* Nested Table Row for Exam Content */}
                      {record.試験内容 && Array.isArray(record.試験内容) && record.試験内容.length > 0 && (
                        <tr>
                          <td colSpan={mainHeaders.length} className="p-2 bg-light">
                            <div className="table-responsive">
                              <table className="table table-sm table-bordered mb-0">
                                <thead className="table-secondary">
                                  <tr>
                                    <th>教科</th>
                                    <th>試験時間</th>
                                    <th>配点</th>
                                  </tr>
                                </thead>
                                <tbody>
                                  {record.試験内容.map((subject, subIndex) => (
                                    <tr key={subIndex}>
                                      <td><ValueRenderer value={subject.教科} /></td>
                                      <td><ValueRenderer value={subject.試験時間} /></td>
                                      <td><ValueRenderer value={subject.配点} /></td>
                                    </tr>
                                  ))}
                                </tbody>
                              </table>
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      })}

      {/* Render other details from the same topic */}
      {otherEntries.length > 0 && <hr />}
      {otherEntries.map(([key, value]) => {
        if (!value) return null;
        return (
          <div key={key} className="mb-4">
            <h3 className="fw-bold">{translate(key)}</h3>
            <div className="ps-2"><ValueRenderer value={value} /></div>
          </div>
        );
      })}
    </div>
  );
}

