        return (
          <div key={year} className="mb-5">
            <h3 className="fw-bold">{`${year}年度 募集要項`}</h3>
            <div className="table-responsive">
              <table className="table table-striped table-bordered">
                <thead className="table-light">
                  <tr>
                    {headers.map(h => <th key={h}>{h}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {yearRecords.map((record, index) => (
                    <tr key={index}>
                      {headers.map(header => (
                        <td key={header}>
                          <ValueRenderer value={record[header]} />
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      })}

      {/* Render other details from the same topic */}
      {otherEntries.length > 0 && <hr />}
      {otherEntries.map(([key, value]) => {
        if (!value) return null;
        return (
          <div key={key} className="mb-4">
            <h3 className="fw-bold">{translate(key)}</h3>
            <div className="ps-2"><ValueRenderer value={value} /></div>
          </div>
        );
      })}
    </div>
  );
}

export default AdmissionsSection;

import React from 'react';
import { useWordMappings } from '../contexts/WordMappingContext';
import ValueRenderer from './ValueRenderer';

// This is the final, correct implementation based on the user's explicit instructions.
function AdmissionsSection({ details }) {
  const { translate } = useWordMappings();

  // Find the key for the main data, e.g., 'unmapped_ja_募集要項'
  const guidelinesKey = Object.keys(details).find(k => k.includes('募集要項') && details[k]);

  // Find all other entries to render below the main tables
  const otherEntries = Object.entries(details).filter(([key]) => 
    key !== guidelinesKey && !['school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'].includes(key)
  );

  let yearlyGuidelines = [];
  if (guidelinesKey && typeof details[guidelinesKey] === 'string') {
    try {
      const parsed = JSON.parse(details[guidelinesKey]);
      if (Array.isArray(parsed)) {
        yearlyGuidelines = parsed;
      }
    } catch (e) {
      console.error("Failed to parse admissions guidelines data:", e);
    }
  }

  return (
    <div className="mt-3 ps-2">
      {/* Main content: map over each year's data */}
      {yearlyGuidelines.sort((a, b) => (b.年度 || 0) - (a.年度 || 0)).map((yearData, index) => {
        const year = yearData.年度;
        const examRecords = yearData.入試日程;

        if (!year || !Array.isArray(examRecords) || examRecords.length === 0) {
          return null;
        }

        return (
          <div key={index} className="mb-5">
            <h3 className="fw-bold">{`${year}年度 募集要項`}</h3>

            {/* For each individual exam record, create the two-table set */}
            {examRecords.map((record, recordIndex) => {
              const { 試験内容, ...mainDetails } = record;
              const mainHeaders = ['入試日', '入試種別', '募集人員', '面接'];
              const examContentHeaders = ['教科', '試験時間', '配点'];

              return (
                <div key={recordIndex} className="mb-4 p-3 border rounded bg-light">

                  {/* Table 1: Main Info */}
                  <div className="table-responsive">
                    <table className="table table-sm table-bordered bg-white mb-2">
                      <thead className="table-light">
                        <tr>
                          {mainHeaders.map(h => <th key={h}>{h}</th>)}
                        </tr>
                      </thead>
                      <tbody>
                        <tr>
                          {mainHeaders.map(h => (
                            <td key={h}>
                              {record[h] != null ? <ValueRenderer value={record[h]} /> : '-'}
                            </td>
                          ))}
                        </tr>
                      </tbody>
                    </table>
                  </div>

                  {/* Table 2: Exam Content */}
                  {試験内容 && Array.isArray(試験内容) && 試験内容.length > 0 && (
                    <div className="table-responsive mt-2">
                      <table className="table table-sm table-bordered mb-0 bg-white">
                        <thead className="table-secondary">
                          <tr>
                            {examContentHeaders.map(h => <th key={h}>{h}</th>)}
                          </tr>
                        </thead>
                        <tbody>
                          {試験内容.map((subject, subIndex) => (
                            <tr key={subIndex}>
                              {examContentHeaders.map(header => (
                                <td key={header}>{
                                  (subject[header] != null && subject[header] !== '') 
                                  ? <ValueRenderer value={subject[header]} /> 
                                  : '-'
                                }</td>
                              ))}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        );
      })}

      {/* Render other details from the same topic */}
      {otherEntries.length > 0 && <hr />}
      {otherEntries.map(([key, value]) => {
        if (!value) return null;
        return (
          <div key={key} className="mb-4">
            <h3 className="fw-bold">{translate(key)}</h3>
            <div className="ps-2"><ValueRenderer value={value} /></div>
          </div>
        );
      })}
    </div>
  );
}

export default AdmissionsSection;

